import {test,expect,type Page} from '@playwright/test';
import {readFileSync} from 'node:fs';
import {mkdir} from 'node:fs/promises';
import path from 'node:path';

// This fixture is generated by ExtendedModelPreviewTest.main using real OBJ, BBModel and Java readers.
const fixtures=JSON.parse(readFileSync(path.resolve('e2e/fixtures/model-format-scenes.json'),'utf8')).scenes;
async function install(page:Page,kind:string) {
  await page.addInitScript(()=>localStorage.setItem('copperbench.ui.locale','en'));
  await page.goto('/');await page.waitForSelector('[data-testid="app-shell"]');
  await page.evaluate(async({scene,kind})=>{
    const url=performance.getEntriesByType('resource').map(e=>e.name).find(url=>new URL(url).pathname==='/src/bridge/index.ts')??'/src/bridge/index.ts';
    const {coreBridge}=await import(url);const original=coreBridge.sendQuery.bind(coreBridge);
    if(kind==='invalid')scene.meshes[0].uv=[];
    if(kind==='checker') {
      const canvas=document.createElement('canvas');canvas.width=canvas.height=128;const context=canvas.getContext('2d')!;
      context.fillStyle='#ba7740';for(let x=0;x<128;x++)for(let y=0;y<128;y++)if((x+y)%2===0)context.fillRect(x,y,1,1);
      const base64=canvas.toDataURL('image/png').split(',')[1];
      scene={kind:'item',layers:['checker'],textures:{checker:{assetId:`asset:${'a'.repeat(64)}`,relativePath:'checker.png',sha256:'a'.repeat(64),mediaType:'image/png',width:128,height:128,size:atob(base64).length,base64}},fingerprint:'checker'};
    }
    if(kind==='many') {
      const texture=Object.keys(scene.textures)[0];scene={...scene,kind:'model',elements:Array.from({length:512},(_,i)=>{
        const x=i%8,y=Math.floor(i/8)%8,z=Math.floor(i/64);return {from:[x*16,y*16,z*16],to:[x*16+15,y*16+15,z*16+15],faces:Object.fromEntries(['north','south','west','east','up','down'].map(face=>[face,{texture}]))};
      }),fingerprint:'many'};
    }
    coreBridge.sendQuery=async(query:any)=>{
      if(query.operation==='list_assets') {
        const result=await original(query),asset=result.data?.assets?.find((asset:any)=>asset.id===`asset:${'1'.repeat(64)}`);
        if(asset)asset.relativePath=kind==='java'?'models/Creature.java':kind==='bbmodel'?'models/rotated.bbmodel':'models/pyramid.obj';
        return result;
      }
      return query.operation==='get_asset_preview'?{messageType:'query_result',schemaVersion:'1.0',requestId:query.requestId,workspaceId:query.workspaceId,operation:query.operation,status:'succeeded',revision:42,
        data:{schemaVersion:'1.0',assetId:query.payload.assetId,sha256:query.payload.expectedSha256,kind:'model',textures:[],scene},diagnostics:[]}:original(query);
    };
  },{scene:fixtures[kind]??fixtures.obj,kind});
  await page.getByTestId('nav-assets').click();await page.getByTestId(`asset-card-asset:${'1'.repeat(64)}`).click();
}
for(const kind of ['obj','bbmodel','java'])test(`${kind} parser output renders its real geometry and rotates`,async({page},info)=>{
  await install(page,kind);const preview=page.getByTestId('model-scene-preview');await expect(preview).toHaveAttribute('data-preview-state','ready');
  const canvas=preview.locator('canvas');expect(Number(await canvas.getAttribute('data-mesh-count'))).toBeLessThanOrEqual(4);
  const before=await canvas.evaluate((c:HTMLCanvasElement)=>c.toDataURL());await preview.getByRole('button',{name:'Rotate left',exact:true}).click();
  await expect.poll(()=>canvas.evaluate((c:HTMLCanvasElement)=>c.toDataURL())).not.toBe(before);
  await preview.getByRole('button',{name:'Zoom in',exact:true}).click();await expect(preview.getByRole('status',{name:'Zoom level'})).toHaveText('116%');
  const directory=path.resolve('../output/model-format-validation');await mkdir(directory,{recursive:true});await page.screenshot({path:path.join(directory,`${kind}-${info.project.name}.png`)});
  if(kind==='java')await expect(preview).toContainText('Default pose');
});
test('high-frequency alpha contours and hundreds of cubes stay in material batches',async({page})=>{
  for(const kind of ['checker','many']) {
    await install(page,kind);const preview=page.getByTestId('model-scene-preview');await expect(preview).toHaveAttribute('data-preview-state','ready',{timeout:15000});
    await expect(preview.locator('canvas')).toHaveAttribute('data-mesh-count','1');
    await preview.getByRole('button',{name:'Rotate left',exact:true}).click();
    await preview.getByRole('button',{name:'Reset view',exact:true}).click();await expect(preview.getByRole('status',{name:'Zoom level'})).toHaveText('100%');
  }
});
test('invalid mesh data has a visible recoverable rendering failure',async({page})=>{
  await install(page,'invalid');const preview=page.getByTestId('model-scene-preview');await expect(preview).toHaveAttribute('data-preview-state','error');
  await expect(preview.getByRole('alert')).toContainText('Could not display the 3D preview');await expect(preview.getByRole('button',{name:'Retry preview'})).toBeVisible();
});
